head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// 실행 중인 케이스 정보
scwin.gVar = { "caseNo" : "", "sentType" : "" };



// 확인 대상 Column (Body Column 인덱스 / 표기명)
scwin.COL_LIST = [
    { "index" : 0, "name" : "gradeS" },
    { "index" : 1, "name" : "gradeC" },
    { "index" : 2, "name" : "gradeK" }
];



// 이전 케이스에서 열린 Excel 파일 선택 레이어를 닫는다.
//  · 닫은 경우 true 를 반환한다. (닫기 처리가 끝나기 전에 다시 열면 ID 중복 경고가 발생하므로 호출부에서 간격을 둔다.)
scwin.closeOpened = function () {
    try {
        var objFrame = document.querySelector("[id$='_excelPop_wframe']");
        if (objFrame === null) return false;

        WebSquare.util.closePopup(objFrame.id.replace("_wframe", ""));
        return true;
    } catch (e) {}

    return false;
};



// type 값만 달리하여 advancedExcelUpload 실행
scwin.runCase = function (strNo, strType) {
    var bClosed = scwin.closeOpened();

    var fnRun = function () {
        target1.advancedExcelUpload({ "wframe" : true, "type" : strType });

        scwin.gVar.caseNo = strNo;

        // 엔진에 실제로 전달된 값은 업로드가 끝나면 비워지므로 호출 직후 바로 읽는다.
        scwin.gVar.sentType = JSON.parse(target1._excelUploadInfo).uploadType;
    };

    // 이전 레이어의 닫기 처리가 끝난 뒤 다음 케이스를 실행한다.
    if (bClosed === true) {
        setTimeout(fnRun, 800);
    } else {
        fnRun();
    }
};



// 업로드 완료 후 Cell 재렌더가 끝나면 결과를 출력한다.
scwin.target1_onfilereadend = function (value) {
    setTimeout(scwin.printResult, 300);
};



// Column 별 표시값 출력
scwin.printResult = function () {
    scwin.setReturnValue("[" + scwin.gVar.caseNo + "] 전달된 type : " + scwin.gVar.sentType);

    var nCnt = target1.getRowCount();
    for (var i = 0; i < nCnt; i++) {
        var arrOut = [];
        for (var k = 0; k < scwin.COL_LIST.length; k++) {
            var objCol = scwin.COL_LIST[k];
            arrOut.push(objCol.name + " [" + scwin.toText(scwin.getCellText(i, objCol.index)) + "]");
        }
        scwin.setReturnValue("Row " + i + " : " + arrOut.join(" | "));
    }

    scwin.setReturnValue("");
};



// 빈 값 표기
scwin.toText = function (value) {
    if (value === undefined || value === null || value === "") return "(빈값)";
    return value;
};



// GridView 에 렌더된 Cell 표시값 조회
scwin.getCellText = function (nRow, nCol) {
    var objTd = document.querySelector("td[id*='" + target1.id + "_cell_" + nRow + "_" + nCol + "']");
    if (objTd === null) return "";

    return (objTd.textContent || "").trim();
};



// ① type "0"
scwin.btn_case1_onclick = function () {
    scwin.runCase("①", "0");
};

// ② type "1"
scwin.btn_case2_onclick = function () {
    scwin.runCase("②", "1");
};

// ③ type "2"
scwin.btn_case3_onclick = function () {
    scwin.runCase("③", "2");
};
